import { Button } from "@charcuterie/ui"
import { useState } from "react"
import { createPerson } from "../state/people"
import { setStatus } from "../state/store"

/** Add somebody. The id comes from the name, is generated by the server, and never moves after. */
export function AddPerson() {
  const [name, setName] = useState("")
  const [isSaving, setIsSaving] = useState(false)
  const trimmed = name.trim()

  const add = async () => {
    if (!trimmed || isSaving) return
    setIsSaving(true)
    try {
      await createPerson(trimmed)
      setStatus(`${trimmed} added`, "ok")
      setName("")
    } catch (error) {
      setStatus(
        `Could not add: ${(error as Error).message}`,
        "err",
      )
    } finally {
      setIsSaving(false)
    }
  }

  return (
    <div className="peopleadd">
      <label className="field">
        Add a person
        <input
          id="peopleadd-name"
          maxLength={60}
          onChange={(event) => setName(event.target.value)}
          onKeyDown={(event) => {
            if (event.key === "Enter") {
              event.preventDefault()
              event.stopPropagation()
              void add()
            }
          }}
          placeholder="e.g. Ada Lovelace"
          type="text"
          value={name}
        />
      </label>
      <Button
        id="peopleaddbtn"
        intent="accent"
        isDisabled={!trimmed || isSaving}
        onClick={() => void add()}
      >
        Add
      </Button>
    </div>
  )
}
